const JA_MESSAGES = {
  ...EN_MESSAGES,
  ...JA_MESSAGES_MANUAL,
  ...JA_MESSAGES_COMMON,
  ...JA_MESSAGES_CONVERSATION,
  ...JA_MESSAGES_WORKSPACE,
  ...JA_MESSAGES_PROVIDERS,
  ...JA_MESSAGES_SOURCE_CONTROL,
  ...JA_MESSAGES_COMPLETION,
} as const satisfies WebMessages;

export const WEB_MESSAGES: Readonly<Record<ResolvedAppLocale, WebMessages>> = {
  en: EN_MESSAGES,
  "zh-CN": ZH_CN_MESSAGES,
  ja: JA_MESSAGES,
};

const WEB_MESSAGE_KEY_BY_ENGLISH_SOURCE = new Map<string, WebMessageKey>();
for (const [key, source] of Object.entries(EN_MESSAGES) as ReadonlyArray<
  readonly [WebMessageKey, string]
>) {
  if (!source.includes("{") && !WEB_MESSAGE_KEY_BY_ENGLISH_SOURCE.has(source)) {
    WEB_MESSAGE_KEY_BY_ENGLISH_SOURCE.set(source, key);
  }
}

function escapeMessagePattern(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

const WEB_MESSAGE_TEMPLATES = (
  Object.entries(EN_MESSAGES) as ReadonlyArray<readonly [WebMessageKey, string]>
)
  .filter(([, source]) => /\{[A-Za-z][A-Za-z0-9]*\}/u.test(source))
  .map(([key, source]) => {
    const placeholders: string[] = [];
    let lastIndex = 0;
    let pattern = "^";
    for (const match of source.matchAll(/\{([A-Za-z][A-Za-z0-9]*)\}/gu)) {
      pattern += escapeMessagePattern(source.slice(lastIndex, match.index));
      pattern += "([\\s\\S]*?)";
      placeholders.push(match[1]!);
      lastIndex = match.index + match[0].length;
    }
    pattern += `${escapeMessagePattern(source.slice(lastIndex))}$`;
    return { key, placeholders, pattern: new RegExp(pattern, "u") };
  });

