/** Translate static UI copy supplied by upstream components as English source text. */
export function translateWebSource(locale: ResolvedAppLocale, source: string): string {
  if (locale === "zh-CN") {
    const translatedSource = ZH_CN_SOURCE_MESSAGES[source];
    if (translatedSource !== undefined) return translatedSource;
  }
  if (locale === "ja") {
    const translatedSource = JA_SOURCE_MESSAGES[source];
    if (translatedSource !== undefined) return translatedSource;
  }
  const key = WEB_MESSAGE_KEY_BY_ENGLISH_SOURCE.get(source);
  if (key !== undefined) return WEB_MESSAGES[locale][key];
  for (const template of WEB_MESSAGE_TEMPLATES) {
    const match = template.pattern.exec(source);
    if (!match) continue;
    const values = Object.fromEntries(
      template.placeholders.map((placeholder, index) => [placeholder, match[index + 1] ?? ""]),
    );
    return translateWebMessage(locale, template.key, values);
  }
  return source;
}

export function translateWebMessage(
  locale: ResolvedAppLocale,
  key: WebMessageKey,
  values?: WebMessageValues,
): string {
  const message = WEB_MESSAGES[locale][key];
  if (!values) return message;

  return message.replace(/\{([A-Za-z][A-Za-z0-9]*)\}/g, (placeholder, name: string) => {
    const value = values[name];
    return value === undefined ? placeholder : String(value);
  });
}
